class Scene:
    def enter(self):
        raise NotImplementedError


class Forest(Scene):
    def enter(self):
        print("You are in a misty forest. Paths: cabin / lake")
        return "cabin"


class Cabin(Scene):
    def enter(self):
        print("A warm cabin. You rest. The end.")
        return "finished"


class Map:
    scenes = {
        "forest": Forest(),
        "cabin": Cabin(),
    }

    def __init__(self, start):
        self.start = start

    def next_scene(self, name):
        return self.scenes.get(name)


class Engine:
    def __init__(self, scene_map):
        self.scene_map = scene_map

    def play(self):
        current = self.scene_map.next_scene(self.scene_map.start)
        while current:
            nxt = current.enter()
            if nxt == "finished":
                break
            current = self.scene_map.next_scene(nxt)


Engine(Map("forest")).play()
